ALTER TABLE public.orders ADD COLUMN inspection_type text CHECK (inspection_type IN ('inspection_only', 'inspection_and_service')); ALTER TABLE public.bicycle_inspections ADD COLUMN inspection_type text NOT NULL DEFAULT 'inspection_and_service' CHECK (inspection_type IN ('inspection_only', 'inspection_and_service')); ALTER TABLE public.bicycle_inspections ADD COLUMN service_decision text NOT NULL DEFAULT 'accepted' CHECK (service_decision IN ('pending', 'accepted', 'declined')); UPDATE public.bicycle_inspections i SET inspection_type = o.inspection_type, service_decision = CASE WHEN o.inspection_type = 'inspection_only' THEN 'pending' ELSE 'accepted' END FROM public.orders o WHERE i.order_id = o.id AND o.inspection_type IS NOT NULL; CREATE OR REPLACE FUNCTION public.sync_inspection_choice() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.order_id IS NOT NULL THEN SELECT COALESCE(o.inspection_type, 'inspection_and_service') INTO NEW.inspection_type FROM public.orders o WHERE o.id = NEW.order_id; IF TG_OP = 'INSERT' THEN NEW.service_decision := CASE WHEN NEW.inspection_type = 'inspection_only' THEN 'pending' ELSE 'accepted' END; END IF; END IF; RETURN NEW; END; $$; CREATE TRIGGER sync_inspection_choice BEFORE INSERT ON public.bicycle_inspections FOR EACH ROW EXECUTE FUNCTION public.sync_inspection_choice();